  HTU(8) = HESS(5)*(U1(8)*U2(114))+HESS(6)*(U1(9)*U2(114))+HESS(832)*(U1(114)*U2(114))
  HTU(9) = HESS(7)*(U1(9)*U2(114))+HESS(8)*(U1(10)*U2(114))+HESS(833)*(U1(114)*U2(114))
  HTU(10) = HESS(9)*(U1(10)*U2(114))+HESS(33)*(U1(19)*U2(114))+HESS(834)*(U1(114)*U2(114))
  HTU(11) = HESS(10)*(U1(11)*U2(114))+HESS(815)*(U1(113)*U2(114))+HESS(835)*(U1(114)*U2(114))+HESS(1057)*(U1(119)&
              &*U2(114))
  HTU(12) = 0
  HTU(13) = HESS(12)*(U1(13)*U2(114))+HESS(108)*(U1(38)*U2(114))+HESS(248)*(U1(72)*U2(114))+HESS(408)*(U1(91)*U2(114))&
              &+HESS(836)*(U1(114)*U2(114))+HESS(1122)*(U1(121)*U2(114))
  HTU(14) = 0
  HTU(15) = HESS(17)*(U1(15)*U2(114))+HESS(487)*(U1(96)*U2(114))+HESS(664)*(U1(108)*U2(114))+HESS(837)*(U1(114)*U2(114))&
              &+HESS(973)*(U1(116)*U2(114))
  HTU(16) = HESS(1)*(U1(4)*U2(114))+HESS(18)*(U1(16)*U2(114))+HESS(838)*(U1(114)*U2(114))
  HTU(17) = HESS(19)*(U1(16)*U2(114))+HESS(23)*(U1(17)*U2(114))+HESS(839)*(U1(114)*U2(114))
  HTU(18) = HESS(24)*(U1(17)*U2(114))+HESS(28)*(U1(18)*U2(114))+HESS(840)*(U1(114)*U2(114))
